  "stuSess.refundContactNote": "หากต้องการขอคืนเงิน โปรดติดต่อ <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">มีคำถามหรือปัญหา? ติดต่อ <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a></p><p class=\"font-semibold text-emerald-900\">เริ่มดำเนินการคืนเงินผ่าน Stripe แล้ว</p><p class=\"text-emerald-800 mt-1\">เงินคืนเข้าบัตรมักใช้เวลาประมาณ <strong>5–10 วันทำการ</strong> (ขึ้นอยู่กับธนาคาร) หากไม่ได้รับภายในเวลาปกติ โปรดส่งอีเมลถึง <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a></p>",
  "stuSess.refundSuccessManualTutor": "<p>คาบนี้ดูเหมือนไม่ได้ชำระผ่าน Tutlio Stripe (เช่น โอนธนาคารหรือเงินสด) จึงไม่มีการคืนเงินอัตโนมัติที่นี่</p><p class=\"mt-2\">หากต้องการขอคืนเงิน โปรดติดต่อติวเตอร์ <strong>{tutor}</strong> ผ่านอีเมลหรือข้อมูลจากรายการจอง หรือข้อมูลที่ติวเตอร์ให้โดยตรง</p>",
  "stuSess.refundSuccessManualOrg": "<p>คาบนี้ดูเหมือนไม่ได้ชำระผ่าน Tutlio Stripe (เช่น โอนธนาคารหรือเงินสด) จึงไม่มีการคืนเงินอัตโนมัติที่นี่</p><p class=\"mt-2\">เนื่องจากคุณเรียนผ่านองค์กร โปรดติดต่อ<strong>ผู้ดูแลองค์กร</strong>ผ่านติวเตอร์หรือช่องทางติดต่อที่องค์กรเผยแพร่</p>",
