  "landing.faq.whatIsQ": "Tutlio คืออะไร?",
  "landing.faq.whatIsA": "Tutlio คือแพลตฟอร์มจัดการงานสอนพิเศษที่ช่วยให้ติวเตอร์ส่วนตัวและโรงเรียนกวดวิชาจัดตาราง รับชำระเงิน สื่อสารกับนักเรียน และติดตามคาบเรียนได้ในที่เดียว",
